        <thead><tr>{["Paciente","Servicio / profesional","Fecha","Cita","Revisión manual","Acción"].map(label=><th key={label}>{label}</th>)}</tr></thead>
        <tbody>{items.map(a=><tr key={a.id} data-appointment-id={a.id}>
